/* eslint-disable no-useless-escape */
import { getStoreConfig } from '@/auth/api';
import { COOKIE_LIFETIME, LOCALHOST } from '@/auth/configs/cookieConfigs';

export const STORE_CONFIG_SESSION_KEY = 'storeConfig';

export const getCookie = (cookieName: string) => {
  const cookies = document.cookie.split(';');
  let foundValue;

  cookies.forEach((cookie) => {
    const [name, value] = cookie.trim().split('=');
    if (name === cookieName) {
      foundValue = decodeURIComponent(value);
    }
  });

  return foundValue;
};

export const deleteCookie = (cookieName: string) => {
  document.cookie = `${cookieName}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`;
};

/**
 * Shared attribute string for every auth cookie, so the token and its metadata
 * cannot end up with different scopes or lifetimes.
 *
 * The `Secure` flag is omitted on localhost (fix for Safari).
 *
 * @param lifetime - `Max-Age=<seconds>` string for the cookie
 */
export const getAuthCookieAttributes = (lifetime: string) => {
  const secureFlag = LOCALHOST.includes(window.location.hostname)
    ? ''
    : 'Secure';

  return `path=/; ${lifetime}; SameSite=Lax; ${secureFlag};`;
};

export interface AuthCookieContext {
  /** `Max-Age=<seconds>` derived from `customerAccessTokenLifetime`. */
  lifetime: string;
  /** Website the token is being issued for. */
  websiteCode: string;
}

/**
 * Resolves the store config needed to persist a freshly issued token.
 *
 * Bypasses both caches on purpose. The `storeConfig` in `sessionStorage` is a
 * UI cache that any component can populate for any website on the same origin,
 * and the HTTP cache is keyed by an endpoint URL that is identical across
 * websites, so neither can be trusted to describe the website the token
 * belongs to.
 *
 * Refreshes the `sessionStorage` cache as a side effect, so UI consumers stay
 * aligned with the website the user just logged into.
 */
export const getAuthCookieContext = async (): Promise<AuthCookieContext> => {
  try {
    const storeConfig = await getStoreConfig({ cache: 'no-store' });

    if (storeConfig) {
      sessionStorage.setItem(
        STORE_CONFIG_SESSION_KEY,
        JSON.stringify(storeConfig)
      );
    }

    return {
      lifetime: `Max-Age=${
        storeConfig?.customerAccessTokenLifetime || COOKIE_LIFETIME
      }`,
      websiteCode: storeConfig?.websiteCode || '',
    };
  } catch (error) {
    console.error('getAuthCookieContext() Error:', error);

    // Without a website code the switch check is skipped, which preserves the
    // pre-existing behavior instead of risking a false logout.
    return { lifetime: `Max-Age=${COOKIE_LIFETIME}`, websiteCode: '' };
  }
};
