import { events } from '@adobe-commerce/event-bus';
import { COOKIE_NAMES } from '@/auth/configs/cookieConfigs';
import { removeFetchGraphQlHeader } from '@/auth/api/fetch-graphql';
import { deleteCookie } from './cookieUtils';
import { emitAuthGroupIdEvent } from './emitAuthGroupId';
import { EventsList, publishEvents } from './acdl';

/**
 * Tears down all client-side authentication state.
 *
 * Every logout path must go through here so the sequences cannot drift apart —
 * see `revokeCustomerToken` (user-initiated) and the website-switch check in
 * `initialize` (forced).
 *
 * @param authHeader - Name of the authorization header to remove
 */
export const clearAuthState = async (authHeader: string): Promise<void> => {
  Object.values(COOKIE_NAMES).forEach((cookieName) => deleteCookie(cookieName));

  removeFetchGraphQlHeader(authHeader);

  await emitAuthGroupIdEvent();

  events.emit('authenticated', false);

  publishEvents(EventsList.SIGN_OUT, {});
};
