import { getStoreConfigResponse } from '@/auth/types';
import { fetchGraphQl } from '../fetch-graphql';
import { GET_STORE_CONFIG } from './graphql/getStoreConfig.graphql';
import { handleNetworkError } from '@/auth/lib/network-error';
import { transformStoreConfig } from '@/auth/data/transforms';
import { StoreConfigModel } from '@/auth/data/models';
import { handleFetchError } from '@/auth/lib/fetch-error';

export interface GetStoreConfigOptions {
  /**
   * Cache mode for the request. Defaults to `force-cache`, which suits UI
   * configuration.
   *
   * Callers that need the response to describe the *current* website must pass
   * `no-store`: the endpoint URL is identical across websites, so a cached
   * response can belong to a different one.
   */
  cache?: RequestCache;
}

export const getStoreConfig = async ({
  cache = 'force-cache',
}: GetStoreConfigOptions = {}): Promise<StoreConfigModel> => {
  return await fetchGraphQl(GET_STORE_CONFIG, {
    method: 'GET',
    cache,
  })
    .then((response: getStoreConfigResponse) => {
      if (response.errors?.length) return handleFetchError(response.errors);

      return transformStoreConfig(response);
    })
    .catch(handleNetworkError);
};
