import { Initializer, Model, Config } from '@adobe-commerce/elsie/lib';
import { Lang } from '@adobe-commerce/elsie/i18n';
import { getCookie } from '@/auth/lib/cookieUtils';
import {
  CustomerModel,
  SHARE_CUSTOMER_ACCOUNTS_SCOPE,
} from '@/auth/data/models';
import {
  verifyToken,
  getCustomerRolePermissions,
  getAdobeCommerceOptimizerData,
  getStoreConfig,
} from '@/auth/api';
import { events } from '@adobe-commerce/event-bus';
import { COOKIE_NAMES } from '@/auth/configs/cookieConfigs';
import { clearAuthState } from '@/auth/lib/clearAuthState';

type ConfigProps = {
  langDefinitions?: Lang;
  authHeaderConfig: {
    header: string;
    tokenPrefix: string;
  };
  customerPermissionRoles?: boolean;
  adobeCommerceOptimizer?: boolean;
  models?: {
    CustomerModel?: Model<CustomerModel>;
  };
};

const _authenticated = new Config<boolean | undefined>(undefined);

/**
 * Clears auth when the user switched websites and accounts are scoped
 * per-website, so the stale token never reaches the backend.
 *
 * Compares the website the token was issued for (persisted next to the token in
 * `COOKIE_NAMES.auth_dropin_website_code`) against the website currently being
 * served. Both the scope and the current website code come from an uncached
 * `storeConfig`, since a cached one could describe the previous website and
 * either mask a real switch or fabricate one.
 *
 * Only covers websites sharing a domain: on separate domains the auth cookie is
 * not sent at all, so there is nothing to clear. Tokens issued before this
 * cookie existed have no website recorded, so the check is skipped and
 * `verifyToken` keeps handling them.
 *
 * @returns `true` when auth was cleared.
 */
const checkWebsiteSwitchRequiresLogout = async (
  authHeader: string
): Promise<boolean> => {
  try {
    const tokenWebsiteCode = getCookie(COOKIE_NAMES.auth_dropin_website_code);

    if (!tokenWebsiteCode) return false;

    const freshConfig = await getStoreConfig({ cache: 'no-store' });

    if (
      freshConfig?.shareCustomerAccountsScope !==
      SHARE_CUSTOMER_ACCOUNTS_SCOPE.PER_WEBSITE
    ) {
      return false;
    }

    if (!freshConfig.websiteCode) return false;

    if (freshConfig.websiteCode !== tokenWebsiteCode) {
      await clearAuthState(authHeader);
      return true;
    }
  } catch {
    // Fall through to verifyToken, which handles the invalid token.
  }

  return false;
};

export const initialize = new Initializer<ConfigProps>({
  init: async (config) => {
    const defaultConfig = {
      authHeaderConfig: {
        header: 'Authorization',
        tokenPrefix: 'Bearer',
      },
      customerPermissionRoles: false,
      adobeCommerceOptimizer: false,
    };

    const mergedConfig = { ...defaultConfig, ...config };

    initialize.config.setConfig(mergedConfig);

    const token = getCookie(COOKIE_NAMES.auth_dropin_user_token);

    const clearedForWebsiteSwitch = token
      ? await checkWebsiteSwitchRequiresLogout(
          mergedConfig.authHeaderConfig.header
        )
      : false;

    const [authenticated] = await Promise.all([
      clearedForWebsiteSwitch
        ? Promise.resolve(false)
        : verifyToken(
            mergedConfig.authHeaderConfig.header,
            mergedConfig.authHeaderConfig.tokenPrefix,
            mergedConfig.adobeCommerceOptimizer
          ),
      // Skipped once auth is cleared: no customer, no roles.
      mergedConfig.customerPermissionRoles && token && !clearedForWebsiteSwitch
        ? getCustomerRolePermissions()
        : Promise.resolve(),
      // Independent of auth state, so it must load on a website switch too.
      mergedConfig.adobeCommerceOptimizer
        ? getAdobeCommerceOptimizerData()
        : Promise.resolve(),
    ]);

    _authenticated.setConfig(authenticated);
  },

  listeners: () => [
    events.on('authenticated', (next) => {
      const prev = _authenticated.getConfig();

      if (prev !== undefined && next !== prev) {
        _authenticated.setConfig(next);
        const { customerPermissionRoles, adobeCommerceOptimizer } =
          initialize.config.getConfig();
        if (customerPermissionRoles) {
          getCustomerRolePermissions();
        }
        if (adobeCommerceOptimizer) {
          getAdobeCommerceOptimizerData();
        }
      }
    }),
  ],
});

export const config = initialize.config;
